-- =================================================================================================
-- (by hand) Rules the database also enforces
-- =================================================================================================
ALTER TABLE "academic_years" ADD CONSTRAINT "academic_years_dates_check" CHECK ("starts_on" < "ends_on");
-- At most one ACTIVE academic year per institution.
CREATE UNIQUE INDEX "academic_years_one_active_per_institution"
  ON "academic_years" ("institution_id") WHERE "status" = 'ACTIVE';
ALTER TABLE "class_levels" ADD CONSTRAINT "class_levels_position_check" CHECK ("position" BETWEEN 1 AND 6);
ALTER TABLE "classes" ADD CONSTRAINT "classes_level_check" CHECK ("level" BETWEEN 1 AND 6);
-- A class code is unique among its siblings (top-level classes: per campus).
CREATE UNIQUE INDEX "classes_sibling_code_key"
  ON "classes" ("campus_id", COALESCE("parent_id", '00000000-0000-0000-0000-000000000000'::uuid), "code");

-- =================================================================================================
-- (by hand) Row security: the same rule as every organization table
-- =================================================================================================
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['academic_years', 'class_levels', 'classes', 'batches'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY organization_isolation ON %I
         USING (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))
         WITH CHECK (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))', t);
  END LOOP;
END
$$;

-- =================================================================================================
-- (by hand) Default class levels for institutions that already exist
-- (new institutions get them from src/modules/academic/default-levels.ts)
-- =================================================================================================
SELECT set_config('app.bypass_rls', 'on', false);

INSERT INTO "class_levels" ("id", "organization_id", "institution_id", "position", "name", "updated_at")
SELECT uuidv7(), i."organization_id", i."id", l."position", l."name", now()
FROM "institutions" i
JOIN (VALUES
  ('JUNIOR_COLLEGE', 1, 'Year'), ('JUNIOR_COLLEGE', 2, 'Group'), ('JUNIOR_COLLEGE', 3, 'Section'),
  ('DEGREE_COLLEGE', 1, 'Year'), ('DEGREE_COLLEGE', 2, 'Course'), ('DEGREE_COLLEGE', 3, 'Section'),
  ('ENGINEERING_COLLEGE', 1, 'Year'), ('ENGINEERING_COLLEGE', 2, 'Branch'), ('ENGINEERING_COLLEGE', 3, 'Section'),
  ('SCHOOL', 1, 'Class'), ('SCHOOL', 2, 'Section')
) AS l("type", "position", "name") ON l."type" = i."type"::text;

SELECT set_config('app.bypass_rls', 'off', false);
